import math


def sieve(n):
    mark = [0]*(n+1)
    prime = []
    for i in range(3, n+1, 2):
        if not mark[i]:
            for j in range(3*i, n+1, i+i):
                mark[j] = 1
    prime.append(2)
    for i in range(3, n+1, 2):
        if not mark[i]:
            prime.append(i)

    return prime


def ispowerof2(x):
    if x and not (x & (x-1)):
        return 0
    else:
        return 1


