import sys

border = 1 << 30


def build(x=0):
    res = [0, 0]

    i = 0
    while x and i < 30:
        if x & 1:
            res[1] += (1 << i)
        x >>= 1
        i += 1

    i = 0
    while x:
        if x & 1:
            res[0] += (1 << i)
        x >>= 1
        i += 1

    return res


n, r, k = map(int, sys.stdin.buffer.readline().decode('utf-8').split())
