    if '-v' in argv or override:
        print(*args)

class Spider():
    def __init__(self, x, y, d):
        self.x = x
        self.y = y
        self.d = d

    def get_copy(self):
        return Spider(self.x, self.y, self.d)

    def move(self):
        if self.d == 'R':
            self.x += 1
        elif self.d == 'L':
            self.x -= 1
        elif self.d == 'U':
            self.y -= 1
        elif self.d == 'D':
            self.y += 1
        else:
            raise Exception('WHAT HAVE YOU DONE', self.d)

