    ulders = [s for s in rders if s.y == (i - s.x)]
    sightings += len(ulders)
    prnt('uld', len(ulders))

    urders = [s for s in lders if s.y == (s.x - i)]
    sightings += len(urders)
    prnt('urd', len(urders))

    return str(sightings)


