class SMT:
    def __init__(self,n,query_fn,I):
        self.h = 1
        while 1 << self.h < n:
            self.h += 1
        self.n=1<<self.h
        self.qf=query_fn
        self.tree = [I] * (self.n<<1)
        self.lazy = [0] * self.n


    def build(self, v):
        for k in range(len(v)):
            self.tree[k + self.n] = v[k]
        for k in range(self.n - 1, 0, -1):
            self.tree[k] = self.qf(self.tree[2*k],self.tree[2 * k + 1])

    def apply(self, x, val):
        self.tree[x] = val
        if x < self.n:
            self.lazy[x] = 1


    def pushup(self, x):
        self.tree[x]=self.qf(self.tree[2*x],self.tree[2*x+1])

    def push(self, x):#pushdown
        if self.lazy[x]:
            self.apply(x * 2,0)
            self.apply(x * 2+ 1,0)
            self.lazy[x] = 0

    def set(self,p,x):
        p+=self.n
        for i in range(self.h,0,-1):self.push(p>>i)
        self.tree[p]=x
        for i in range(1,self.h+1):self.pushup(p>>i)

    def get(self,p):
        p+=self.n
        for i in range(self.h,0,-1):self.push(p>>i)
        return self.tree[p]

    def update(self, l, r, h):#左闭右闭
        l += self.n
        r += self.n
        l0=l
        r0=r
        for i in range(self.h,0,-1):
            if (((l>>i)<<i)!=l):self.push(l>>i)
            if ((((r+1)>>i)<<i)!=r+1):self.push(r>>i)
        while l <= r:
            if l & 1:
                self.apply(l, h)
                l += 1
            if not r & 1:
                self.apply(r, h)
                r -= 1
            l>>=1
            r>>=1
        for i in range(1,self.h+1):
            if (((l0>>i)<<i)!=l0):self.pushup(l0>>i)
            if ((((r0+1)>>i)<<i)!=r0+1):
                self.pushup(r0>>i)

    def query(self, l, r):
        l += self.n
        r += self.n
        for i in range(self.h,0,-1):
            if (((l>>i)<<i)!=l):self.push(l>>i)
            if ((((r+1)>>i)<<i)!=r+1):self.push(r>>i)
        ans = 0
        while l <= r:
            if l & 1:
                ans = self.qf(ans, self.tree[l])
                l += 1
            if not r & 1:
                ans = self.qf(ans, self.tree[r])
                r -= 1
            l >>= 1; r >>= 1
        return ans

