    def find_centroid(g):
        p    = {}
        size = {}

        p[1] = -1
        Q    = [1] 

        i = 0
        while i < len(Q):
            u = Q[i]

            for v in g[u]:
                if p[u] == v: continue
                p[v] = u
                Q.append(v)
            i+=1    

        for u in Q[::-1]:
            size[u] = 1

            for v in g[u]:
                if p[u] == v:
                    continue
                size[u] += size[v]

        cur = 1  
        n = size[cur]

        while True:
            max_ = n - size[cur] 
            ind_ = p[cur]

            for v in g[cur]:
                if v == p[cur]: continue

                if size[v] > max_:  
                    max_ = size[v]
                    ind_ = v

            if max_ <= n // 2:
                return cur

            cur = ind_

